/**
 * Ensemblr's Claude Code mods, registered together from the one hooks module
 * the plugin's `hooks/hooks.json` names. Each mod is UI-free: Ensemblr hosts
 * Claude Code over the SDK, where no pane, band, status line, or toast draws.
 */
import type { Register } from 'claude-code';

import { registerCompactKeeper } from './compact-keeper.ts';
import { registerGitGuard } from './git-guard.ts';
import { registerSecretRedact } from './secret-redact.ts';
import { registerTicketContext } from './ticket-context.ts';

/**
 * Registers every mod's hooks.
 * @param on - The plugin's registrar.
 */
export const register: Register = (on) => {
	registerGitGuard(on);
	registerSecretRedact(on);
	registerCompactKeeper(on);
	registerTicketContext(on);
};

files.hooks/compact-keeper.ts:
/**
 * compact-keeper: tells every compaction what an Ensemblr orchestrator cannot
 * work without afterwards. A summary that drops a child's `agentSessionId` or a
 * queued `jobId` leaves the agent unable to wait on, steer, or close the work it
 * already started, and it re-spawns or re-queues instead.
 */
import type { EngineInterface, On } from 'claude-code';

/** How long reading the current branch may take before compaction goes on without it. */
const BRANCH_PROBE_TIMEOUT_MS = 5_000;

/** What every compaction is told to carry over verbatim. */
export const KEEP_INSTRUCTIONS = `This session runs inside Ensemblr. The summary must carry these over verbatim, each id copied exactly, because the next turn cannot recover them from anywhere else:
- Every child conversation started with ensemblr_start_conversation: its agentSessionId, its chatTabId, its title, whether it is still running or settled, and the gist of its report if one came back.
- Every compute-queue job queued with ensemblr_run_queued: its jobId, the command, and its last known state (queued, running, finished with exit code, timed out).
- The workspace's git branch, and whether work on it is committed, pushed, or has a pull request.
- Every open diff-review comment id from ensemblr_get_diff_comments or ensemblr_add_diff_comments, which ones were fixed, and which are still open and why.
- Every decision made so far — by the user, or by you and stated to the user — with its reason, and every question still waiting on the user.`;

/**
 * Reads the branch the session's checkout is on.
 * @param $ - The engine interface.
 * @returns The branch name, or null when git cannot say.
 */
async function readBranch($: EngineInterface): Promise<string | null> {
	try {
		const probe = await $.process.run(['git', 'branch', '--show-current'], {
			timeoutMs: BRANCH_PROBE_TIMEOUT_MS,
		});
		const branch = probe.stdout.trim();
		return probe.exitCode === 0 && branch !== '' ? branch : null;
	} catch {
		return null;
	}
}

/**
 * Joins the person's or another plugin's instructions with Ensemblr's.
 * @param instructions - The instructions already set, if any.
 * @param branch - The current branch, if known.
 * @returns The instructions the summarizer is given.
 */
function composeInstructions(
	instructions: string | undefined,
	branch: string | null,
): string {
	const branchLine =
		branch === null ? null : `The workspace branch is currently \`${branch}\`.`;
	return [instructions?.trim() || null, KEEP_INSTRUCTIONS, branchLine]
		.filter((part) => part !== null)
		.join('\n\n');
}

/**
 * Registers compact-keeper's compaction hook.
 * @param on - The plugin's registrar.
 */
export function registerCompactKeeper(on: On): void {
	on('session.compact', async ($, e, next) =>
		next({
			...e,
			instructions: composeInstructions(e.instructions, await readBranch($)),
		}),
	);
}

files.hooks/git-guard.ts:
/**
 * git-guard: refuses, before they run, the git moves Ensemblr's playbook forbids
 * — `git branch -m`, the shared stash stack outside its recipe, and git pointed
 * at a checkout other than this session's own. The playbook already says all
 * of this; a model that forgets it now hears it at the moment it matters.
 */
import type { EngineInterface, On } from 'claude-code';

import { findGitInvocations, type GitTarget } from './git-command.ts';
import { judgeGitInvocation, type WorktreeScope } from './git-policy.ts';

/** How long the one-off `git rev-parse` that finds the worktree may take. */
const SCOPE_PROBE_TIMEOUT_MS = 5_000;

/**
 * Resolves a path through symbolic links, so a link into a sibling checkout is
 * judged where it lands; a path that does not exist keeps its own spelling.
 * @param $ - The engine interface.
 * @param path - An absolute path.
 * @returns The real path, or the path as given.
 */
async function realPathOf($: EngineInterface, path: string): Promise<string> {
	try {
		return (await $.fs.stat(path, { resolve: true })).realPath ?? path;
	} catch {
		return path;
	}
}

/**
 * Finds the checkout this session owns: the worktree root and its git directory,
 * from git itself, falling back to the session's directory alone.
 * @param $ - The engine interface.
 * @returns The session's worktree scope.
 */
async function readWorktreeScope($: EngineInterface): Promise<WorktreeScope> {
	const cwd = await $.session.cwd();
	try {
		const probe = await $.process.run(
			['git', 'rev-parse', '--show-toplevel', '--absolute-git-dir'],
			{ cwd, timeoutMs: SCOPE_PROBE_TIMEOUT_MS },
		);
		const [root, gitDir] = probe.stdout.trim().split('\n');
		if (probe.exitCode === 0 && root && gitDir) {
			return {
				gitDir: await realPathOf($, gitDir),
				root: await realPathOf($, root),
			};
		}
	} catch {
		return { gitDir: null, root: await realPathOf($, cwd) };
	}
	return { gitDir: null, root: await realPathOf($, cwd) };
}

/**
 * Resolves a target's path through symbolic links.
 * @param $ - The engine interface.
 * @param target - One redirection of git.
 * @returns The target with its real path.
 */
async function realTarget(
	$: EngineInterface,
	target: GitTarget,
): Promise<GitTarget> {
	return target.path === null
		? target
		: { ...target, path: await realPathOf($, target.path) };
}

/**
 * Decides a Bash command: the first git invocation in it that breaks a rule.
 * @param $ - The engine interface.
 * @param command - The Bash command line.
 * @param scope - The session's worktree scope.
 * @returns The refusal, or null to let the command run.
 */
async function judgeCommand(
	$: EngineInterface,
	command: string,
	scope: WorktreeScope,
): Promise<string | null> {
	const home = (await $.env.get('HOME')) ?? null;
	const invocations = findGitInvocations(command, {
		cwd: await $.session.cwd(),
		home,
	});
	for (const invocation of invocations) {
		const targets = await Promise.all(
			invocation.targets.map((target) => realTarget($, target)),
		);
		const denial = judgeGitInvocation({ ...invocation, targets }, scope);
		if (denial !== null) {
			return denial;
		}
	}
	return null;
}

/**
 * Registers git-guard's Bash hook.
 * @param on - The plugin's registrar.
 */
export function registerGitGuard(on: On): void {
	let scope: Promise<WorktreeScope> | null = null;
	on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
		if (!/\bgit\b/.test(e.command)) {
			return next(e);
		}
		scope ??= readWorktreeScope($);
		const denial = await judgeCommand($, e.command, await scope);
		return denial === null ? next(e) : { deny: denial };
	});
}

files.hooks/secret-redact.ts:
/**
 * secret-redact: replaces the exact values of this workspace's secrets — its
 * Infisical secrets, its Keychain environment rows, and the control tokens the
 * app minted — with `[redacted:NAME]` in every row the conversation keeps,
 * before the model reads it or the next request sends it. A tool's structured
 * record beside its result is stored as the tool made it, so the transcript
 * file and a host drawing from that record can still show the raw output.
 *
 * The values never reach this module. Ensemblr matches them in its own process
 * (`redactText` over the control server) and answers with the redacted text, so
 * there is no file, variable, or reply here that would hand the model a secret
 * it could otherwise not see. The session's own control token is the one value
 * this module holds — the model's environment already carries it — and it is
 * replaced locally too, so it stays hidden even while the app is unreachable.
 *
 * Rows are rewritten at `session.append`, the one place every row passes, so a
 * secret is caught whichever tool, attachment, or delivery carried it. The
 * person's own prompt and slash commands are left as typed: a value they paste
 * on purpose is theirs to hand the model. When the app does not answer within
 * {@link CONTROL_DEADLINE_MS}, the row goes on with the local pass alone:
 * holding the session hostage to a slow main process is the worse failure.
 */
import type { EngineInterface, HttpResponse, On } from 'claude-code';

import {
	buildInvokeRequest,
	CONTROL_DEADLINE_MS,
	type ControlEndpoint,
	readInvokeData,
	toControlEndpoint,
} from './control.ts';
import {
	createTextRedactor,
	redactBlocks,
	type TextRedactor,
} from './row-redaction.ts';

/** The doors whose rows the person typed, which are never rewritten. */
const PERSON_DOORS = new Set(['prompt', 'command']);

/** The placeholder the control token becomes. */
const TOKEN_PLACEHOLDER = '[redacted:ENSEMBLR_CONTROL_TOKEN]';

/**
 * Reads the control endpoint Ensemblr injected into this session.
 * @param $ - The engine interface.
 * @returns The endpoint, or null outside an Ensemblr session.
 */
async function readEndpoint(
	$: EngineInterface,
): Promise<ControlEndpoint | null> {
	return toControlEndpoint(
		await $.env.get('ENSEMBLR_CONTROL_URL'),
		await $.env.get('ENSEMBLR_CONTROL_TOKEN'),
	);
}

/**
 * Calls the app, giving up once the deadline passes.
 * @param $ - The engine interface.
 * @param request - The request to send.
 * @returns The response, or null on a failure or a timeout.
 */
async function fetchWithinDeadline(
	$: EngineInterface,
	request: ReturnType<typeof buildInvokeRequest>,
): Promise<HttpResponse | null> {
	const timer = new AbortController();
	const deadline = $.clock
		.sleep(CONTROL_DEADLINE_MS, { signal: timer.signal })
		.then(
			() => null,
			() => new Promise<never>(() => undefined),
		);
	try {
		return await Promise.race([
			$.http.fetch(request.url, request.init),
			deadline,
		]);
	} catch {
		return null;
	} finally {
		timer.abort();
	}
}

/**
 * Has the app redact one piece of text against the workspace's secrets.
 * @param $ - The engine interface.
 * @param endpoint - The session's control endpoint.
 * @param piece - Text within the op's size limit.
 * @returns The redacted text, or the piece unchanged when the app did not answer.
 */
async function redactRemotely(
	$: EngineInterface,
	endpoint: ControlEndpoint,
	piece: string,
): Promise<string> {
	const request = buildInvokeRequest(endpoint, 'redactText', { text: piece });
	const response = await fetchWithinDeadline($, request);
	const data = (response === null ? null : readInvokeData(response.text)) as {
		text?: unknown;
	} | null;
	return typeof data?.text === 'string' ? data.text : piece;
}

/**
 * Builds this session's text redactor, or null outside Ensemblr.
 * @param $ - The engine interface.
 * @returns The redactor.
 */
async function createSessionRedactor(
	$: EngineInterface,
): Promise<TextRedactor | null> {
	const endpoint = await readEndpoint($);
	return endpoint === null
		? null
		: createTextRedactor(endpoint.token, TOKEN_PLACEHOLDER, (piece) =>
				redactRemotely($, endpoint, piece),
			);
}

/**
 * Registers secret-redact's row hook.
 * @param on - The plugin's registrar.
 */
export function registerSecretRedact(on: On): void {
	on('session.append', async ($, e, next) => {
		const redact = PERSON_DOORS.has(e.door)
			? null
			: await createSessionRedactor($);
		if (redact === null) {
			return next(e);
		}
		const content = await redactBlocks(e.message.content, redact);
		return content === e.message.content
			? next(e)
			: next({ ...e, message: { ...e.message, content: [...content] } });
	});
}

files.hooks/ticket-context.ts:
/**
 * ticket-context: puts the Linear issue a workspace was created from into the
 * context blocks of a conversation's first message — its identifier, title, and
 * description — so the agent starts from the ticket's requirements rather than
 * from a one-line prompt, and so does every later conversation in the workspace.
 *
 * The block rides the person's first message, which secret-redact leaves as
 * typed, so it goes through `redactText` here: a key pasted into a ticket is as
 * much a secret as one printed by a tool.
 */
import type { EngineInterface, On } from 'claude-code';

import {
	buildInvokeRequest,
	CONTROL_DEADLINE_MS,
	type ControlEndpoint,
	readInvokeData,
	toControlEndpoint,
} from './control.ts';

/** The linked issue as `getLinkedIssue` answers it. */
interface LinkedIssue {
	description: string | null;
	identifier: string;
	title: string;
	url: string | null;
}

/** The name the block renders under. */
export const BLOCK_NAME = 'ensemblrLinkedIssue';

/** The tag the description is quoted inside. */
const DESCRIPTION_TAG = 'issue-description';

/** Anything a model would read as the description's closing tag. */
const CLOSING_TAG = new RegExp(`<\\s*/\\s*${DESCRIPTION_TAG}\\s*>`, 'gi');

/** The placeholder the control token becomes. */
const TOKEN_PLACEHOLDER = '[redacted:ENSEMBLR_CONTROL_TOKEN]';

/**
 * Narrows `getLinkedIssue`'s payload to an issue.
 * @param data - The op's `data`.
 * @returns The issue, or null when there is none or the payload is malformed.
 */
function readIssue(data: unknown): LinkedIssue | null {
	const issue = (data as { issue?: unknown } | null)?.issue;
	if (typeof issue !== 'object' || issue === null) {
		return null;
	}
	const { description, identifier, title, url } = issue as Record<
		string,
		unknown
	>;
	return typeof identifier === 'string' && typeof title === 'string'
		? {
				description: typeof description === 'string' ? description : null,
				identifier,
				title,
				url: typeof url === 'string' ? url : null,
			}
		: null;
}

/**
 * Renders the block's text. The description is quoted as data, since it is
 * whatever the team wrote on the ticket and not an instruction from the user.
 * @param issue - The linked issue.
 * @returns The block text.
 */
function renderIssueBlock(issue: LinkedIssue): string {
	const heading = `This workspace was created from Linear issue ${issue.identifier}: ${issue.title}`;
	const link = issue.url === null ? null : `URL: ${issue.url}`;
	const quoted = issue.description
		?.trim()
		.replace(CLOSING_TAG, `<\\/${DESCRIPTION_TAG}>`);
	const description = quoted
		? `Issue description, quoted from Linear (requirements context; the user's own messages take precedence over it):\n<${DESCRIPTION_TAG}>\n${quoted}\n</${DESCRIPTION_TAG}>`
		: 'The issue has no description.';
	return [heading, link, description]
		.filter((part) => part !== null)
		.join('\n');
}

/**
 * Calls one control op, giving up once the deadline passes.
 * @param $ - The engine interface.
 * @param endpoint - The session's control endpoint.
 * @param op - The op name.
 * @param args - The op's arguments.
 * @returns The op's `data`, or null on a refusal, a failure, or a timeout.
 */
async function callControl(
	$: EngineInterface,
	endpoint: ControlEndpoint,
	op: string,
	args: Record<string, unknown>,
): Promise<unknown> {
	const request = buildInvokeRequest(endpoint, op, args);
	const timer = new AbortController();
	const deadline = $.clock
		.sleep(CONTROL_DEADLINE_MS, { signal: timer.signal })
		.then(
			() => null,
			() => new Promise<never>(() => undefined),
		);
	try {
		const response = await Promise.race([
			$.http.fetch(request.url, request.init),
			deadline,
		]);
		return response === null ? null : readInvokeData(response.text);
	} catch {
		return null;
	} finally {
		timer.abort();
	}
}

/**
 * Builds the linked issue's block, its text already redacted.
 * @param $ - The engine interface.
 * @returns The block text, or null outside Ensemblr or when none is linked.
 */
async function buildIssueBlock($: EngineInterface): Promise<string | null> {
	const endpoint = toControlEndpoint(
		await $.env.get('ENSEMBLR_CONTROL_URL'),
		await $.env.get('ENSEMBLR_CONTROL_TOKEN'),
	);
	if (endpoint === null) {
		return null;
	}
	const issue = readIssue(await callControl($, endpoint, 'getLinkedIssue', {}));
	if (issue === null) {
		return null;
	}
	const text = renderIssueBlock(issue)
		.split(endpoint.token)
		.join(TOKEN_PLACEHOLDER);
	const redacted = (await callControl($, endpoint, 'redactText', { text })) as {
		text?: unknown;
	} | null;
	return typeof redacted?.text === 'string' ? redacted.text : text;
}

/**
 * Registers ticket-context's first-message hook.
 * @param on - The plugin's registrar.
 */
export function registerTicketContext(on: On): void {
	on('prompt.context', async ($, e, next) => {
		const [context, text] = await Promise.all([next(e), buildIssueBlock($)]);
		const isAlreadyThere = context.blocks.some(
			(block) => block.name === BLOCK_NAME,
		);
		return text === null || isAlreadyThere
			? context
			: {
					...context,
					blocks: [...context.blocks, { name: BLOCK_NAME, text }],
				};
	});
}

files.hooks/git-command.ts:
/**
 * Finds the `git` invocations in a Bash command and what each one points at:
 * the subcommand and its arguments, and every path that moves git off the
 * session's own checkout (`cd`/`pushd`, `-C`, `--git-dir`, `--work-tree`,
 * `GIT_DIR`, `GIT_WORK_TREE`), resolved against the directory the command
 * runs in.
 */
import { SUBSHELL_CLOSE, SUBSHELL_OPEN, splitCommands } from './shell-words.ts';

/** How a path redirected git: a directory change, a global option, or an environment variable. */
export type GitTargetSource =
	| 'cd'
	| '-C'
	| '--git-dir'
	| '--work-tree'
	| 'GIT_DIR'
	| 'GIT_WORK_TREE';

/** One redirection of git, its path absolute, or null when it cannot be read. */
export interface GitTarget {
	path: string | null;
	source: GitTargetSource;
}

/** One `git` the command would start. */
export interface GitInvocation {
	args: readonly string[];
	subcommand: string | null;
	targets: readonly GitTarget[];
}

/** The directory a command runs in (null once a `cd` lost it) and the home directory. */
export interface ShellContext {
	cwd: string | null;
	home: string | null;
}

/** Words that lead a simple command without being the program it runs. */
const COMMAND_PREFIXES = new Set([
	'!',
	'{',
	'}',
	'builtin',
	'command',
	'do',
	'elif',
	'else',
	'exec',
	'if',
	'nohup',
	'then',
	'time',
	'until',
	'while',
]);

/** A program that runs another one: its option table and the positionals before the program. */
interface Wrapper {
	/** Options that run the program in another directory. */
	chdirOptions?: ReadonlySet<string>;
	positionals: number;
	/** Options that name a placeholder the program's words are filled from. */
	replaceOptions?: ReadonlySet<string>;
	valueOptions: ReadonlySet<string>;
}

/** Wrappers a command in good faith is plausibly started through. */
const WRAPPERS: ReadonlyMap<string, Wrapper> = new Map([
	[
		'env',
		{
			chdirOptions: new Set(['-C', '--chdir']),
			positionals: 0,
			valueOptions: new Set(['-u', '--unset', '-S', '-C', '--chdir']),
		},
	],
	['nice', { positionals: 0, valueOptions: new Set(['-n', '--adjustment']) }],
	[
		'sudo',
		{
			chdirOptions: new Set(['-D', '--chdir']),
			positionals: 0,
			valueOptions: new Set([
				'-u',
				'-g',
				'-C',
				'-D',
				'--chdir',
				'-h',
				'-p',
				'-U',
			]),
		},
	],
	[
		'timeout',
		{
			positionals: 1,
			valueOptions: new Set(['-s', '--signal', '-k', '--kill-after']),
		},
	],
	[
		'xargs',
		{
			positionals: 0,
			replaceOptions: new Set(['-I', '--replace']),
			valueOptions: new Set([
				'-a',
				'-d',
				'-E',
				'-e',
				'-I',
				'-L',
				'-n',
				'-P',
				'-s',
			]),
		},
	],
]);

/** The placeholder `xargs -i` and a bare `--replace` fill. */
const XARGS_DEFAULT_PLACEHOLDER = '{}';

/** `cd` and `pushd` flags that change how a path resolves, not which. */
const CD_FLAGS = /^-[LPe@]+$/;

/** Environment variables that point git at another repository or checkout. */
const TARGET_VARIABLES = new Set<GitTargetSource>(['GIT_DIR', 'GIT_WORK_TREE']);

/** A shell variable assignment, `NAME=value`. */
const ASSIGNMENT = /^([A-Za-z_][A-Za-z0-9_]*)=(.*)$/s;

/** Git global options that take the next word as their value. */
const VALUE_OPTIONS = new Set(['-c', '--config-env', '--namespace']);

/**
 * Expands a leading `~` the way the shell would.
 * @param path - The path as written.
 * @param home - The home directory, or null when unknown.
 * @returns The expanded path, or null when it needs a home nobody knows.
 */
function expandHome(path: string, home: string | null): string | null {
	if (path !== '~' && !path.startsWith('~/')) {
		return path;
	}
	return home === null ? null : `${home}${path.slice(1)}`;
}

/**
 * Resolves a path lexically against a directory, `~` expanded.
 * @param base - Absolute directory relative paths start from, or null when unknown.
 * @param path - The path as written.
 * @param home - The home directory, or null when unknown.
 * @returns The absolute path, or null when it cannot be read without running the shell.
 */
function resolvePath(
	base: string | null,
	path: string,
	home: string | null,
): string | null {
	const expanded =
		path.includes('$') || path.includes('`') ? null : expandHome(path, home);
	if (expanded === null || (base === null && !expanded.startsWith('/'))) {
		return null;
	}
	const joined = expanded.startsWith('/') ? expanded : `${base}/${expanded}`;
	const kept: string[] = [];
	for (const part of joined.split('/')) {
		if (part === '..') {
			kept.pop();
		} else if (part !== '' && part !== '.') {
			kept.push(part);
		}
	}
	return `/${kept.join('/')}`;
}

/**
 * Reads a `git` command's global options, from the word after `git` to its subcommand.
 * @param words - The words after `git`.
 * @param context - Where the command runs, for resolving `-C` and friends.
 * @param inherited - Targets the environment already set (`GIT_DIR=...`).
 * @returns The invocation.
 */
function readGitWords(
	words: readonly string[],
	context: ShellContext,
	inherited: readonly GitTarget[],
): GitInvocation {
	const targets = [...inherited];
	let directory = context.cwd;
	let index = 0;
	while (index < words.length) {
		const word = words[index] ?? '';
		if (!word.startsWith('-')) {
			break;
		}
		const [flag, attached] = word.split(/=(.*)/s, 2);
		const value = attached ?? words[index + 1] ?? '';
		if (word === '-C') {
			directory =
				value === '' ? null : resolvePath(directory, value, context.home);
			targets.push({ path: directory, source: '-C' });
			index += 2;
		} else if (flag === '--git-dir' || flag === '--work-tree') {
			targets.push({
				path: resolvePath(directory, value, context.home),
				source: flag,
			});
			index += attached === undefined ? 2 : 1;
		} else {
			index += VALUE_OPTIONS.has(word) ? 2 : 1;
		}
	}
	return {
		args: words.slice(index + 1),
		subcommand: words[index] ?? null,
		targets,
	};
}

/**
 * Collects the git targets a run of assignments sets, resolved against the cwd.
 * @param assignments - `NAME=value` words.
 * @param context - Where the command runs.
 * @returns The targets among them.
 */
function targetsFromAssignments(
	assignments: readonly string[],
	context: ShellContext,
): GitTarget[] {
	return assignments.flatMap((assignment) => {
		const [, name, value] = ASSIGNMENT.exec(assignment) ?? [];
		return name && TARGET_VARIABLES.has(name as GitTargetSource)
			? [
					{
						path: resolvePath(context.cwd, value ?? '', context.home),
						source: name as GitTargetSource,
					},
				]
			: [];
	});
}

/** What a run of leading words told about the program they start. */
interface Prefixes {
	assignments: string[];
	/** The directory a wrapper runs the program in, as written; absent when none. */
	directory?: string;
	/** Placeholders a wrapper fills the program's words from. */
	placeholders: string[];
}

/**
 * Splits an option from a value written onto it: `--chdir=/x`, or a short
 * option that takes a value written without a space (`-I{}`, `-n5`).
 * @param word - The option word.
 * @param valueOptions - The options that take a value.
 * @returns The option, and its attached value when it has one.
 */
function splitOption(
	word: string,
	valueOptions: ReadonlySet<string>,
): [string, string | undefined] {
	if (word.startsWith('--')) {
		const [flag = word, attached] = word.split(/=(.*)/s, 2);
		return [flag, attached];
	}
	const short = word.slice(0, 2);
	return word.length > 2 && valueOptions.has(short)
		? [short, word.slice(2)]
		: [word, undefined];
}

/**
 * Reads one wrapper option, noting a directory or placeholder it sets.
 * @param wrapper - The wrapper's option table.
 * @param words - One simple command's words.
 * @param index - Index of the option.
 * @param found - What the leading words told so far; updated in place.
 * @returns How many words the option took.
 */
function readWrapperOption(
	wrapper: Wrapper,
	words: readonly string[],
	index: number,
	found: Prefixes,
): number {
	const word = words[index] ?? '';
	const [flag, attached] = splitOption(word, wrapper.valueOptions);
	const value = attached ?? words[index + 1] ?? '';
	if (wrapper.chdirOptions?.has(flag)) {
		found.directory = value;
	}
	if (wrapper.replaceOptions?.has(flag)) {
		const isBareLongForm = flag.startsWith('--') && attached === undefined;
		found.placeholders.push(
			isBareLongForm
				? XARGS_DEFAULT_PLACEHOLDER
				: value || XARGS_DEFAULT_PLACEHOLDER,
		);
	}
	if (word === '-i' && wrapper.replaceOptions) {
		found.placeholders.push(XARGS_DEFAULT_PLACEHOLDER);
	}
	return attached === undefined && wrapper.valueOptions.has(flag) ? 2 : 1;
}

/**
 * Skips a wrapper's options and leading positionals.
 * @param words - One simple command's words.
 * @param start - Index of the first word after the wrapper's name.
 * @param wrapper - The wrapper's option table.
 * @param found - What the leading words told so far; updated in place.
 * @returns Index of the first word of the program it runs.
 */
function skipWrapper(
	words: readonly string[],
	start: number,
	wrapper: Wrapper,
	found: Prefixes,
): number {
	let index = start;
	while ((words[index] ?? '').startsWith('-')) {
		index += readWrapperOption(wrapper, words, index, found);
	}
	return index + wrapper.positionals;
}

/**
 * Drops the words that lead a command without naming its program: shell
 * keywords, wrappers such as `sudo`, `env` or `timeout` and their options,
 * and assignments. A word a wrapper fills from a placeholder (`xargs -I {}`)
 * cannot be known without running the command, so it keeps a `$` in its place.
 * @param words - One simple command's words.
 * @returns What the leading words told, and the words from the program on.
 */
function stripPrefixes(
	words: readonly string[],
): Prefixes & { program: readonly string[] } {
	const found: Prefixes = { assignments: [], placeholders: [] };
	let index = 0;
	while (index < words.length) {
		const word = words[index] ?? '';
		const wrapper = WRAPPERS.get(word);
		if (ASSIGNMENT.test(word)) {
			found.assignments.push(word);
		} else if (wrapper) {
			index = skipWrapper(words, index + 1, wrapper, found);
			continue;
		} else if (!COMMAND_PREFIXES.has(word)) {
			break;
		}
		index += 1;
	}
	const program = words
		.slice(index)
		.map((word) =>
			found.placeholders.reduce(
				(filled, placeholder) => filled.replaceAll(placeholder, '$'),
				word,
			),
		);
	return { ...found, program };
}

/**
 * Whether a word names the git program, bare or by path.
 * @param word - The program word.
 * @returns True for `git` and `/usr/bin/git`.
 */
function isGit(word: string | undefined): boolean {
	return word === 'git' || (word?.endsWith('/git') ?? false);
}

/** Where the shell stands while a command line is read. */
interface ShellState {
	cwd: string | null;
	exported: readonly GitTarget[];
	pushed: readonly (string | null)[];
}

/**
 * Resolves where `cd` or `pushd` lands.
 * @param state - Where the shell stands.
 * @param args - The command's arguments.
 * @param home - The home directory.
 * @returns The new directory, or null when it cannot be read (`cd -`, an unknown flag).
 */
function changeDirectory(
	state: ShellState,
	args: readonly string[],
	home: string | null,
): string | null {
	const operands = args.filter((arg) => !CD_FLAGS.test(arg));
	const [target] = operands;
	if (target === '-' || target?.startsWith('-')) {
		return null;
	}
	return resolvePath(state.cwd, target ?? '~', home);
}

/**
 * Applies one simple command to where the shell stands.
 * @param state - Where the shell stands before it.
 * @param program - The command, prefixes stripped.
 * @param home - The home directory.
 * @returns Where the shell stands after it.
 */
function applyShellCommand(
	state: ShellState,
	program: readonly string[],
	home: string | null,
): ShellState {
	const [name, ...rest] = program;
	switch (name) {
		case 'cd':
			return { ...state, cwd: changeDirectory(state, rest, home) };
		case 'pushd':
			return {
				...state,
				cwd: rest.length === 0 ? null : changeDirectory(state, rest, home),
				pushed: [...state.pushed, state.cwd],
			};
		case 'popd':
			return {
				...state,
				cwd: state.pushed.length === 0 ? null : (state.pushed.at(-1) ?? null),
				pushed: state.pushed.slice(0, -1),
			};
		case 'export':
			return {
				...state,
				exported: [
					...state.exported,
					...targetsFromAssignments(rest, { cwd: state.cwd, home }),
				],
			};
		default:
			return state;
	}
}

/**
 * Finds every `git` a Bash command would start, following `cd`, `pushd`,
 * `export`, `env -C`, and subshells through the command, so a git run after
 * changing directory, a relative `-C`, or a `GIT_DIR` exported earlier in the
 * line is read where it lands. A `cd` to a directory that cannot be read
 * without running the shell (`cd "$(git rev-parse --show-toplevel)"`, `cd -`)
 * is not counted as leaving the worktree: it is how agents return to it.
 * @param command - The Bash command line.
 * @param context - The directory the command starts in and the home directory.
 * @returns Each git invocation, in order.
 */
export function findGitInvocations(
	command: string,
	context: ShellContext,
): GitInvocation[] {
	const { home } = context;
	let state: ShellState = { cwd: context.cwd, exported: [], pushed: [] };
	const subshells: ShellState[] = [];
	const found: GitInvocation[] = [];
	for (const words of splitCommands(command)) {
		const { assignments, directory, program } = stripPrefixes(words);
		const [name, ...rest] = program;
		if (words.length === 1 && name === SUBSHELL_OPEN) {
			subshells.push(state);
		} else if (words.length === 1 && name === SUBSHELL_CLOSE) {
			state = subshells.pop() ?? state;
		} else if (isGit(name)) {
			const cwd =
				directory === undefined
					? state.cwd
					: resolvePath(state.cwd, directory, home);
			const here: ShellContext = { cwd, home };
			const moved: GitTarget[] =
				cwd === null || cwd === context.cwd
					? []
					: [{ path: cwd, source: 'cd' }];
			found.push(
				readGitWords(rest, here, [
					...moved,
					...state.exported,
					...targetsFromAssignments(assignments, here),
				]),
			);
		} else if (directory === undefined) {
			state = applyShellCommand(state, program, home);
		}
	}
	return found;
}

